app.post('/api/offers/:offerId/accept',async(request,reply)=>{const u=await requireRole(request,reply,'provider');if(!u)return;const{offerId}=request.params as any,c=await pool.connect();try{await c.query('BEGIN');const o=await c.query(`SELECT id,mission_id,provider_id FROM mission_offers WHERE id=$1 AND provider_id=$2 AND status='pending' FOR UPDATE`,[offerId,u.provider_id]);if(!o.rowCount){await c.query('ROLLBACK');return reply.code(404).send({error:'pending offer not found'})}const x=o.rows[0],m=await c.query(`UPDATE missions SET provider_id=$1,status='assigned',updated_at=NOW() WHERE id=$2 AND provider_id IS NULL RETURNING *`,[x.provider_id,x.mission_id]);if(!m.rowCount){await c.query(`UPDATE mission_offers SET status='expired',responded_at=NOW() WHERE id=$1`,[offerId]);await c.query('COMMIT');return reply.code(409).send({error:'mission already taken'})}await c.query(`UPDATE mission_offers SET status=CASE WHEN id=$1 THEN 'accepted' ELSE 'expired' END,responded_at=NOW() WHERE mission_id=$2`,[offerId,x.mission_id]);await c.query('COMMIT');return{mission:m.rows[0]}}catch(e){await c.query('ROLLBACK');throw e}finally{c.release()}});
app.post('/api/offers/:offerId/decline',async(request,reply)=>{const u=await requireRole(request,reply,'provider');if(!u)return;const{offerId}=request.params as any,r=await pool.query(`UPDATE mission_offers SET status='declined',responded_at=NOW() WHERE id=$1 AND provider_id=$2 AND status='pending' RETURNING *`,[offerId,u.provider_id]);if(!r.rowCount)return reply.code(404).send({error:'pending offer not found'});return{offer:r.rows[0]}});
async function transitionMission(request:any,reply:any,from:string[],to:string,col:string){const u=await requireRole(request,reply,'provider');if(!u)return;const{id}=request.params as any,r=await pool.query(`UPDATE missions SET status=$1,${col}=NOW(),updated_at=NOW() WHERE id=$2 AND provider_id=$3 AND status=ANY($4::text[]) RETURNING *`,[to,id,u.provider_id,from]);if(!r.rowCount)return reply.code(409).send({error:`mission cannot transition to ${to}`});return{mission:r.rows[0]}}
