app.post('/api/missions/:id/complete',async(request,reply)=>{const u=await requireRole(request,reply,'provider');if(!u)return;const{id}=request.params as any;const remainingRequired=await pool.query(`SELECT COUNT(*)::int AS remaining_required_tasks FROM mission_tasks WHERE mission_id=$1 AND required=TRUE AND completed=FALSE`,[id]);if(Number(remainingRequired.rows[0]?.remaining_required_tasks||0)>0)return reply.code(409).send({error:'Toutes les tâches obligatoires doivent être cochées avant de terminer la job.',remainingTasks:Number(remainingRequired.rows[0].remaining_required_tasks)});const r=await pool.query(`UPDATE missions SET status='completed',completed_at=NOW(),duration_minutes=GREATEST(1,CEIL(EXTRACT(EPOCH FROM(NOW()-started_at))/60)::int),updated_at=NOW() WHERE id=$1 AND provider_id=$2 AND status='in_progress' AND started_at IS NOT NULL RETURNING *`,[id,u.provider_id]);if(!r.rowCount)return reply.code(409).send({error:'mission cannot be completed'});return{mission:r.rows[0],billing:await finalizeBilling(Number(id))}});
app.get('/api/missions/:id/billing',async(request,reply)=>{const{id}=request.params as any,u=await currentUser(request);if(!u)return reply.code(401).send({error:'authentication required'});const m=await pool.query('SELECT client_id,provider_id,status FROM missions WHERE id=$1',[id]);if(!m.rowCount)return reply.code(404).send({error:'mission not found'});const row=m.rows[0];if(u.role==='client'&&String(row.client_id)!==String(u.client_id))return reply.code(403).send({error:'forbidden'});if(u.role==='provider'&&String(row.provider_id)!==String(u.provider_id))return reply.code(403).send({error:'forbidden'});if(row.status==='completed'&&!(await pool.query('SELECT 1 FROM mission_billing WHERE mission_id=$1',[id])).rowCount)await finalizeBilling(Number(id));const r=await pool.query(`SELECT b.*,p.status payment_status,p.payment_method,p.paid_at,pp.status payout_status,pp.release_at,pp.paid_at payout_paid_at FROM mission_billing b LEFT JOIN payments p ON p.mission_id=b.mission_id AND p.kind='client_charge' LEFT JOIN provider_payouts pp ON pp.mission_id=b.mission_id WHERE b.mission_id=$1`,[id]);if(!r.rowCount)return reply.code(409).send({error:'billing is not ready yet'});return{billing:r.rows[0],paymentsMode:PAYMENTS_MODE}});
app.post('/api/missions/:id/pay/mock',async(request,reply)=>{if(PAYMENTS_MODE==='live')return reply.code(404).send({error:'mock payments disabled'});const u=await requireRole(request,reply,'client');if(!u)return;const{id}=request.params as any,m=await pool.query(`SELECT id,status FROM missions WHERE id=$1 AND client_id=$2`,[id,u.client_id]);if(!m.rowCount)return reply.code(404).send({error:'mission not found'});if(m.rows[0].status!=='completed')return reply.code(409).send({error:'mission must be completed before payment'});const b=await finalizeBilling(Number(id));if(!b)return reply.code(409).send({error:'billing unavailable'});await pool.query(`UPDATE payments SET status='paid',payment_method='mock',provider='mock',paid_at=NOW(),updated_at=NOW() WHERE mission_id=$1 AND kind='client_charge'`,[id]);await pool.query(`UPDATE mission_billing SET status='paid',updated_at=NOW() WHERE mission_id=$1`,[id]);await pool.query(`UPDATE provider_payouts SET status='holding',release_at=NOW()+INTERVAL '7 days',updated_at=NOW() WHERE mission_id=$1`,[id]);return{billing:(await pool.query(`SELECT b.*,p.status payment_status,p.payment_method,p.paid_at,pp.status payout_status,pp.release_at FROM mission_billing b LEFT JOIN payments p ON p.mission_id=b.mission_id AND p.kind='client_charge' LEFT JOIN provider_payouts pp ON pp.mission_id=b.mission_id WHERE b.mission_id=$1`,[id])).rows[0],mock:true}});
