app.post('/api/client/missions/:id/cancel',async(request,reply)=>{const u=await requireRole(request,reply,'client');if(!u)return;const{id}=request.params as any,cx=await pool.connect();try{await cx.query('BEGIN');const mr=await cx.query(`SELECT m.id,m.status,m.provider_id,c.hourly_rate_cents FROM missions m LEFT JOIN categories c ON c.id=m.category_id WHERE m.id=$1 AND m.client_id=$2 FOR UPDATE OF m`,[id,u.client_id]);if(!mr.rowCount){await cx.query('ROLLBACK');return reply.code(404).send({error:'Commande introuvable'})}const m=mr.rows[0];if(['completed','cancelled'].includes(m.status)){await cx.query('ROLLBACK');return reply.code(409).send({error:'Cette commande ne peut plus être annulée'})}const assigned=Boolean(m.provider_id),hourlyRate=Number(m.hourly_rate_cents||DEFAULT_HOURLY_RATE_CENTS),feeCents=assigned?Math.ceil(hourlyRate*MINIMUM_BILLABLE_MINUTES/60):0;await cx.query(`UPDATE missions SET status='cancelled',updated_at=NOW() WHERE id=$1`,[id]);await cx.query(`UPDATE mission_offers SET status='expired',responded_at=NOW() WHERE mission_id=$1 AND status='pending'`,[id]);if(feeCents>0){const commission=Math.ceil(feeCents*PROVIDER_COMMISSION_BPS/10000),providerNet=Math.max(0,feeCents-commission);await cx.query(`INSERT INTO mission_billing(mission_id,hourly_rate_cents,actual_minutes,billable_minutes,subtotal_cents,client_service_fee_bps,client_service_fee_cents,client_total_cents,provider_commission_bps,provider_commission_cents,provider_net_cents,status) VALUES($1,$2,0,$3,$4,0,0,$4,$5,$6,$7,'ready') ON CONFLICT(mission_id) DO UPDATE SET hourly_rate_cents=EXCLUDED.hourly_rate_cents,actual_minutes=0,billable_minutes=EXCLUDED.billable_minutes,subtotal_cents=EXCLUDED.subtotal_cents,client_service_fee_bps=0,client_service_fee_cents=0,client_total_cents=EXCLUDED.client_total_cents,provider_commission_bps=EXCLUDED.provider_commission_bps,provider_commission_cents=EXCLUDED.provider_commission_cents,provider_net_cents=EXCLUDED.provider_net_cents,status='ready',updated_at=NOW()`,[id,hourlyRate,MINIMUM_BILLABLE_MINUTES,feeCents,PROVIDER_COMMISSION_BPS,commission,providerNet]);await cx.query(`INSERT INTO payments(mission_id,amount_cents,currency,status,provider,kind) VALUES($1,$2,'CAD','pending',$3,'client_charge') ON CONFLICT(mission_id,kind) DO UPDATE SET amount_cents=EXCLUDED.amount_cents,status=CASE WHEN payments.status='paid' THEN 'paid' ELSE 'pending' END,updated_at=NOW()`,[id,feeCents,PAYMENTS_MODE]);if(m.provider_id)await cx.query(`INSERT INTO provider_payouts(mission_id,provider_id,amount_cents,status) VALUES($1,$2,$3,'waiting_payment') ON CONFLICT(mission_id) DO UPDATE SET provider_id=EXCLUDED.provider_id,amount_cents=EXCLUDED.amount_cents,status=CASE WHEN provider_payouts.status='paid' THEN 'paid' ELSE 'waiting_payment' END,updated_at=NOW()`,[id,m.provider_id,providerNet])}await cx.query('COMMIT');return{ok:true,cancelled:true,fee_cents:feeCents,assigned,min_billable_minutes:MINIMUM_BILLABLE_MINUTES}}catch(e){await cx.query('ROLLBACK');throw e}finally{cx.release()}});

