// GROQ AI - adaptive category-aware interview and final checklist
app.post('/api/ai/task-next-question',async(request,reply)=>{
  const u=await requireRole(request,reply,'client');if(!u)return;
  if(!GROQ_API_KEY)return reply.code(503).send({error:'AI is not configured on the server'});
  const b=request.body as any,category=String(b?.category||'').trim(),subcategory=String(b?.subcategory||'').trim(),description=String(b?.description||'').trim();
  const answers=Array.isArray(b?.answers)?b.answers.slice(0,12):[];
  if(!category||!subcategory)return reply.code(400).send({error:'category and subcategory are required'});
  if(description.length>3000)return reply.code(400).send({error:'description is too long'});
  if(answers.length>=12)return{ok:true,model:GROQ_MODEL,result:{done:true,question:null},usage:null};
  const history=answers.map((a:any,i:number)=>`${i+1}. Question: ${String(a?.question||'').trim()}\n   Réponse: ${String(a?.answer||'').trim()}`).filter((x:string)=>!x.endsWith('Réponse: ')).join('\n');
  try{
    const response=await fetch('https://api.groq.com/openai/v1/chat/completions',{
      method:'POST',headers:{'Authorization':`Bearer ${GROQ_API_KEY}`,'Content-Type':'application/json'},signal:AbortSignal.timeout(20000),
      body:JSON.stringify({model:GROQ_MODEL,reasoning_effort:'low',messages:[
        {role:'system',content:"Tu es le préposé intelligent de FaisLaJob, une plateforme québécoise de services à domicile. Tu mènes une entrevue comme un prestataire expérimenté du Québec qui doit comprendre exactement la job avant de l'accepter.\n\nTu poses UNE SEULE question à la fois et tu relis TOUTES les réponses précédentes avant de choisir la suivante. Ne répète jamais une question déjà répondue. La prochaine question doit suivre naturellement la réponse précédente.\n\nCRITÈRE ABSOLU AVANT DE TERMINER\nTu ne peux mettre done=true que si au moins UNE ACTION CONCRÈTE demandée au prestataire a été explicitement confirmée par le client ET si les informations nécessaires pour exécuter cette action sont suffisamment claires.\n\nDes informations comme : nombre d'animaux, type de logement, dimensions, étage, accès, produits fournis, équipement fourni, stationnement, comportement d'un animal, état des lieux ou fréquence NE SONT PAS à elles seules une job. Ce sont des renseignements de contexte. Si tu n'as que ce type d'information, continue l'entrevue et demande ce que le prestataire doit réellement FAIRE.\n\nExemple Animaux / Visite à domicile :\n- « 5 chiens » = information de contexte, PAS une tâche.\n- « équipement fourni » = information de contexte, PAS une tâche.\n- Il faut encore demander quelque chose comme « Qu'est-ce que tu veux que le prestataire fasse pendant la visite? » puis proposer, si pertinent, des choix multiples comme Nourrir, Remplir l'eau, Sortir dans la cour, Promener, Administrer un médicament, Autre.\n- Ensuite, approfondis seulement les actions sélectionnées si une précision est nécessaire.\n\nPENSE COMME LE PRESTATAIRE\nAvant done=true, demande-toi : « Si cette demande arrivait dans mon téléphone maintenant, saurais-je précisément ce que je dois faire, sur quoi/qui, dans quelle ampleur et avec quelles contraintes importantes, sans appeler le client? » Si non, pose une autre question.\n\nAu Québec, adapte naturellement tes questions à la catégorie : logement/condo/maison, sous-sol, escaliers, ascenseur, entrée d'auto, galerie, neige, stationnement, pieds/pouces, équipements et réalités saisonnières quand pertinent. Français québécois naturel et professionnel, sans caricature.\n\nPour choice ou multi, ajoute « Autre » lorsque les choix ne couvrent pas toutes les possibilités. Si « Autre » est choisi, l'interface demandera une précision libre. Utilise text si une réponse ouverte est plus appropriée.\n\nNe demande pas l'adresse, la date/heure, le nom, le téléphone, le courriel ni le paiement : l'application s'en occupe ailleurs.\n\nVise généralement 4 à 10 questions. Tu peux aller jusqu'à 12 si nécessaire. Le nombre de questions n'est jamais une raison suffisante pour terminer : la fiche doit être complète."},
        {role:'user',content:`Catégorie: ${category}\nSous-catégorie: ${subcategory}\nNote libre déjà donnée: ${description||'(aucune)'}\n\nHistorique des réponses:\n${history||'(aucune réponse encore)'}\n\nNombre de questions déjà répondues: ${answers.length}`}
      ],response_format:{type:'json_schema',json_schema:{name:'faislajob_next_question',strict:true,schema:{type:'object',properties:{done:{type:'boolean'},question:{type:'object',properties:{question:{type:'string'},help:{type:'string'},inputType:{type:'string',enum:['choice','multi','text']},options:{type:'array',items:{type:'string'}}},required:['question','help','inputType','options'],additionalProperties:false}},required:['done','question'],additionalProperties:false}}}})
    });
    const data=await response.json() as any;
    if(!response.ok){app.log.error({status:response.status,groq:data},'Groq adaptive question failed');return reply.code(502).send({error:'AI provider error',status:response.status});}
    const content=data?.choices?.[0]?.message?.content;if(!content)return reply.code(502).send({error:'AI returned an empty response'});
    const parsed=JSON.parse(content) as any;
    if(parsed?.done)return{ok:true,model:data?.model||GROQ_MODEL,result:{done:true,question:null},usage:data?.usage??null};
    const raw=parsed?.question||{};
    let inputType=['choice','multi','text'].includes(raw.inputType)?raw.inputType:'text';
    let options=Array.isArray(raw.options)?raw.options.map((x:any)=>String(x).trim()).filter(Boolean).slice(0,8):[];
    if((inputType==='choice'||inputType==='multi')&&options.length<2){inputType='text';options=[];}
    if(inputType==='text')options=[];
    // AI_QUEBEC_OTHER_OPTION: keep an escape hatch when the suggested choices are not exhaustive.
    if((inputType==='choice'||inputType==='multi')&&options.length>=2&&options.length<8){const lowered=options.map((x:any)=>String(x).trim().toLowerCase());const hasOther=lowered.some((x:string)=>x==='autre'||x.startsWith('autre '));const yesNo=lowered.length===2&&lowered.some((x:string)=>['oui','yes'].includes(x))&&lowered.some((x:string)=>['non','no'].includes(x));if(!hasOther&&!yesNo)options=[...options,'Autre'];}
    const question={id:`q${answers.length+1}`,question:String(raw.question||'').trim()||'Peux-tu préciser ce qu’il faut faire?',help:String(raw.help||'').trim(),inputType,options};
    return{ok:true,model:data?.model||GROQ_MODEL,result:{done:false,question},usage:data?.usage??null};
  }catch(e){app.log.error(e);return reply.code(502).send({error:'AI request failed'});}
});

app.post('/api/ai/task-list',async(request,reply)=>{
  const u=await requireRole(request,reply,'client');if(!u)return;
  if(!GROQ_API_KEY)return reply.code(503).send({error:'AI is not configured on the server'});
  const b=request.body as any,category=String(b?.category||'').trim(),subcategory=String(b?.subcategory||'').trim(),description=String(b?.description||'').trim();
  const answers=Array.isArray(b?.answers)?b.answers.slice(0,12):[];
  if(!category||!subcategory)return reply.code(400).send({error:'category and subcategory are required'});
  if(description.length>3000)return reply.code(400).send({error:'description is too long'});
  if(!description&&answers.length===0)return reply.code(400).send({error:'client answers are required'});
  const answerText=answers.map((a:any,i:number)=>`${i+1}. [${String(a?.inputType||'text')}] ${String(a?.question||'').trim()} => ${String(a?.answer||'').trim()}`).filter((x:string)=>!x.endsWith('=> ')).join('\n');
  try{
    const response=await fetch('https://api.groq.com/openai/v1/chat/completions',{
      method:'POST',headers:{'Authorization':`Bearer ${GROQ_API_KEY}`,'Content-Type':'application/json'},signal:AbortSignal.timeout(20000),
      body:JSON.stringify({model:GROQ_MODEL,reasoning_effort:'low',messages:[
        {role:'system',content:"Tu es le préposé FaisLaJob au Québec qui transforme une entrevue TERMINÉE en fiche de travail claire pour le prestataire.\n\nÀ ce stade, tu ne poses AUCUNE nouvelle question. questions doit toujours être []. Tu utilises uniquement ce que le client a explicitement confirmé.\n\nDISTINCTION OBLIGATOIRE : TÂCHE vs INFORMATION\nUne TÂCHE est une action concrète que le client demande au prestataire d'effectuer. Une information de contexte n'est jamais une tâche.\n\nExemples qui NE SONT PAS des tâches :\n- « 5 chiens »\n- « équipement fourni »\n- « maison à deux étages »\n- « pas d'ascenseur »\n- « stationnement dans la rue »\n- « environ 20 cm de neige »\n- « produits de nettoyage fournis »\nCes informations peuvent aller dans details d'une tâche pertinente ou dans summary, mais jamais devenir une case à cocher.\n\nExemples de mauvaises tâches interdites :\n- « Observer les 5 chiens » si le client n'a jamais demandé de les observer/surveiller.\n- « Utiliser l'équipement fourni ».\n- « Tenir compte du stationnement ».\n- « Vérifier qu'il y a 20 cm de neige ».\n\nRÈGLE DE L'ACTION EXPLICITE\nChaque tâche doit pouvoir être reliée à une action que le client a explicitement demandée ou sélectionnée. N'invente jamais un verbe d'action à partir d'une simple information.\n\nCHOIX MULTIPLES\nQuand une réponse [multi] représente plusieurs éléments sur lesquels LA MÊME ACTION doit être faite, crée une tâche séparée par élément.\nExemple : « Zones à nettoyer : Salon, Cuisine, Coin repas » devient :\n- Nettoyer le salon\n- Nettoyer la cuisine\n- Nettoyer le coin repas\n\nQuand une réponse [multi] représente plusieurs ACTIONS distinctes, crée aussi une tâche séparée pour chaque action confirmée.\nExemple : « Nourrir, Remplir l'eau, Sortir dans la cour » devient trois tâches distinctes.\n\nPar contre, si un multi contient seulement des contraintes ou de la logistique, n'en fais pas des tâches.\n\nDETAILS\nUtilise details pour les précisions utiles au prestataire liées à la tâche : quantité, nombre d'animaux, matériel fourni, consigne, dimensions, accès ou autre contexte confirmé. Garde les détails courts et lisibles. Ne transforme pas une précision en action.\n\nLes titres doivent être courts, naturels, concrets et cochables. Le summary résume la job et les contraintes importantes. N'ajoute rien qui n'a pas été confirmé. questions=[] toujours."},
        {role:'user',content:`Catégorie: ${category}\nSous-catégorie: ${subcategory}\nNote libre: ${description||'(aucune)'}\n\nEntretien complet:\n${answerText||'(aucune)'}`}
      ],response_format:{type:'json_schema',json_schema:{name:'faislajob_task_list',strict:true,schema:{type:'object',properties:{summary:{type:'string'},tasks:{type:'array',items:{type:'object',properties:{title:{type:'string'},details:{type:'string'},required:{type:'boolean'}},required:['title','details','required'],additionalProperties:false}},questions:{type:'array',items:{type:'string'}}},required:['summary','tasks','questions'],additionalProperties:false}}}})
    });
    const data=await response.json() as any;
    if(!response.ok){app.log.error({status:response.status,groq:data},'Groq checklist failed');return reply.code(502).send({error:'AI provider error',status:response.status});}
    const content=data?.choices?.[0]?.message?.content;if(!content)return reply.code(502).send({error:'AI returned an empty response'});
    const result=JSON.parse(content);return{ok:true,model:data?.model||GROQ_MODEL,result,usage:data?.usage??null};
  }catch(e){app.log.error(e);return reply.code(502).send({error:'AI request failed'});}
});

