app.get('/api/admin/overview',async(request,reply)=>{if(!requireAdmin(request,reply))return;const [missions,clients,providers,revenue,pending]=await Promise.all([pool.query(`SELECT COUNT(*)::int total,COUNT(*) FILTER(WHERE status NOT IN('completed','cancelled'))::int active,COUNT(*) FILTER(WHERE status='offered')::int offered,COUNT(*) FILTER(WHERE status='in_progress')::int in_progress FROM missions`),pool.query(`SELECT COUNT(*)::int total FROM clients`),pool.query(`SELECT COUNT(*)::int total,COUNT(*) FILTER(WHERE is_online)::int online,COUNT(*) FILTER(WHERE status='active')::int active FROM providers`),pool.query(`SELECT COALESCE(SUM(client_total_cents),0)::int total FROM mission_billing WHERE status='paid'`),pool.query(`SELECT COALESCE(SUM(amount_cents),0)::int total FROM provider_payouts WHERE status IN('waiting_payment','holding','ready')`)]);return{missions:missions.rows[0],clients:clients.rows[0],providers:providers.rows[0],revenue_cents:revenue.rows[0].total,pending_payouts_cents:pending.rows[0].total}});
app.get('/api/admin/missions',async(request,reply)=>{if(!requireAdmin(request,reply))return;const q=request.query as any,search=String(q?.search||'').trim(),status=String(q?.status||'').trim();const r=await pool.query(`SELECT m.*,c.name category_name,cl.name client_name,cl.phone client_phone,cl.email client_email,p.name provider_name,p.phone provider_phone,b.client_total_cents,b.provider_net_cents,pay.status payment_status FROM missions m LEFT JOIN categories c ON c.id=m.category_id LEFT JOIN clients cl ON cl.id=m.client_id LEFT JOIN providers p ON p.id=m.provider_id LEFT JOIN mission_billing b ON b.mission_id=m.id LEFT JOIN payments pay ON pay.mission_id=m.id AND pay.kind='client_charge' WHERE ($1='' OR m.status=$1) AND ($2='' OR CAST(m.id AS TEXT) ILIKE '%'||$2||'%' OR cl.name ILIKE '%'||$2||'%' OR COALESCE(p.name,'') ILIKE '%'||$2||'%' OR COALESCE(cl.phone,'') ILIKE '%'||$2||'%') ORDER BY m.created_at DESC LIMIT 200`,[status,search]);return{missions:r.rows}});
app.get('/api/admin/clients',async(request,reply)=>{if(!requireAdmin(request,reply))return;const q=String((request.query as any)?.search||'').trim();return{clients:(await pool.query(`SELECT c.*,COUNT(m.id)::int missions_count,MAX(m.created_at) last_mission_at FROM clients c LEFT JOIN missions m ON m.client_id=c.id WHERE $1='' OR c.name ILIKE '%'||$1||'%' OR COALESCE(c.email,'') ILIKE '%'||$1||'%' OR COALESCE(c.phone,'') ILIKE '%'||$1||'%' GROUP BY c.id ORDER BY c.created_at DESC LIMIT 200`,[q])).rows}});
app.get('/api/admin/providers',async(request,reply)=>{if(!requireAdmin(request,reply))return;const q=String((request.query as any)?.search||'').trim();return{providers:(await pool.query(`SELECT p.*,COALESCE(array_agg(DISTINCT pc.category_id) FILTER(WHERE pc.category_id IS NOT NULL),'{}') category_ids,COUNT(DISTINCT m.id) FILTER(WHERE m.status='completed')::int completed_missions,COUNT(DISTINCT m.id) FILTER(WHERE m.status NOT IN('completed','cancelled'))::int active_missions FROM providers p LEFT JOIN provider_categories pc ON pc.provider_id=p.id LEFT JOIN missions m ON m.provider_id=p.id WHERE $1='' OR p.name ILIKE '%'||$1||'%' OR COALESCE(p.email,'') ILIKE '%'||$1||'%' OR COALESCE(p.phone,'') ILIKE '%'||$1||'%' GROUP BY p.id ORDER BY p.is_online DESC,p.created_at DESC LIMIT 200`,[q])).rows}});
