app.post('/api/admin/categories',async(request,reply)=>{if(!requireAdmin(request,reply))return;const b=request.body as any,id=String(b?.id||'').trim().toLowerCase(),name=String(b?.name||'').trim(),hourlyRateCents=Math.round(Number(b?.hourlyRateCents));if(!id||!/^[a-z0-9-]+$/.test(id))return reply.code(400).send({error:'Identifiant de catégorie invalide'});if(!name)return reply.code(400).send({error:'Le nom est requis'});if(!Number.isFinite(hourlyRateCents)||hourlyRateCents<=0)return reply.code(400).send({error:'Le tarif horaire doit être supérieur à 0'});try{const r=await pool.query('INSERT INTO categories(id,name,hourly_rate_cents) VALUES($1,$2,$3) RETURNING id,name,hourly_rate_cents',[id,name,hourlyRateCents]);return reply.code(201).send({category:r.rows[0]})}catch(e:any){if(e?.code==='23505')return reply.code(409).send({error:'Cette catégorie existe déjà'});throw e}});
