app.get('/api/client/promotions',async(request,reply)=>{const u=await requireRole(request,reply,'client');if(!u)return;const completed=Number((await pool.query(`SELECT COUNT(*)::int count FROM missions WHERE client_id=$1 AND status='completed'`,[u.client_id])).rows[0]?.count||0);const r=await pool.query(`SELECT p.*,COALESCE((SELECT COUNT(*)::int FROM promotion_redemptions pr WHERE pr.promotion_id=p.id AND pr.client_id=$1),0)::int uses_by_client FROM promotions p WHERE p.active=TRUE AND (p.starts_at IS NULL OR p.starts_at<=NOW()) AND (p.ends_at IS NULL OR p.ends_at>=NOW()) ORDER BY p.created_at DESC`,[u.client_id]);const promotions=r.rows.map((p:any)=>{const triggerCount=Number(p.trigger_count||0),uses=Number(p.uses_by_client||0),maxUses=p.max_uses_per_client==null?null:Number(p.max_uses_per_client);let eligible=true,progress=100;if(p.trigger_type==='after_orders'){eligible=completed>=triggerCount;progress=triggerCount<=0?100:Math.min(100,Math.round(completed/triggerCount*100))}else if(p.trigger_type==='first_orders'){eligible=completed<triggerCount;progress=triggerCount<=0?100:Math.min(100,Math.round(completed/triggerCount*100))}if(maxUses!==null&&uses>=maxUses)eligible=false;return{...p,completed_orders:completed,eligible,progress}});return{promotions,completed_orders:completed}});
