app.post('/api/admin/promotions',async(request,reply)=>{if(!requireAdmin(request,reply))return;const b=request.body as any,name=String(b?.name||'').trim(),description=String(b?.description||'').trim()||null,kind=String(b?.kind||'fixed'),value=Math.round(Number(b?.value)),triggerType=String(b?.triggerType||'always'),triggerCount=Math.max(0,Math.round(Number(b?.triggerCount||0))),minOrderCents=Math.max(0,Math.round(Number(b?.minOrderCents||0))),startsAt=b?.startsAt||null,endsAt=b?.endsAt||null,maxUses=b?.maxUsesPerClient==null||b.maxUsesPerClient===''?null:Math.max(1,Math.round(Number(b.maxUsesPerClient)));if(!name)return reply.code(400).send({error:'Le nom est requis'});if(!['fixed','percent'].includes(kind))return reply.code(400).send({error:'Type de rabais invalide'});if(!Number.isFinite(value)||value<=0)return reply.code(400).send({error:'Valeur de rabais invalide'});if(kind==='percent'&&value>10000)return reply.code(400).send({error:'Le pourcentage ne peut pas dépasser 100 %'});if(!['always','after_orders','first_orders'].includes(triggerType))return reply.code(400).send({error:'Déclencheur invalide'});const r=await pool.query(`INSERT INTO promotions(name,description,kind,value,trigger_type,trigger_count,min_order_cents,starts_at,ends_at,active,max_uses_per_client) VALUES($1,$2,$3,$4,$5,$6,$7,$8,$9,TRUE,$10) RETURNING *`,[name,description,kind,value,triggerType,triggerCount,minOrderCents,startsAt,endsAt,maxUses]);return reply.code(201).send({promotion:r.rows[0]})});
