// RECURRING SERVICE PLANS
app.get('/api/service-plans',async(request)=>{const q=request.query as any,categoryId=String(q?.category_id||'').trim();const params:any[]=[];let where=`WHERE p.active=TRUE AND (p.starts_at IS NULL OR p.starts_at<=NOW()) AND (p.ends_at IS NULL OR p.ends_at>=NOW())`;if(categoryId){params.push(categoryId);where+=` AND p.category_id=$1`}const r=await pool.query(`SELECT p.*,c.name category_name FROM recurring_service_plans p JOIN categories c ON c.id=p.category_id ${where} ORDER BY p.category_id,p.created_at DESC`,params);return{plans:r.rows}});
app.get('/api/admin/service-plans',async(request,reply)=>{if(!requireAdmin(request,reply))return;const r=await pool.query(`SELECT p.*,c.name category_name,COALESCE((SELECT COUNT(*)::int FROM client_subscriptions s WHERE s.plan_id=p.id AND s.status='active'),0)::int subscribers FROM recurring_service_plans p JOIN categories c ON c.id=p.category_id ORDER BY p.created_at DESC`);return{plans:r.rows}});
app.post('/api/admin/service-plans',async(request,reply)=>{if(!requireAdmin(request,reply))return;const b=request.body as any,categoryId=String(b?.categoryId||'').trim(),name=String(b?.name||'').trim(),description=String(b?.description||'').trim()||null,triggerType=String(b?.triggerType||'weekly'),triggerConfig=b?.triggerConfig&&typeof b.triggerConfig==='object'?b.triggerConfig:{},pricingType=String(b?.pricingType||'per_minute'),priceCents=Math.max(0,Math.round(Number(b?.priceCents||0))),sameTeam=Boolean(b?.sameTeam),maxInterventions=b?.maxInterventions==null||b.maxInterventions===''?null:Math.max(1,Math.round(Number(b.maxInterventions))),startsAt=b?.startsAt||null,endsAt=b?.endsAt||null;if(!categoryId||!name)return reply.code(400).send({error:'Catégorie et nom requis'});if(!['snow_accumulation','weekly','interval','manual'].includes(triggerType))return reply.code(400).send({error:'Type de déclenchement invalide'});if(!['per_minute','per_visit','monthly','seasonal'].includes(pricingType))return reply.code(400).send({error:'Type de prix invalide'});if(triggerType==='snow_accumulation'){const thresholds=Array.isArray(triggerConfig.thresholds_cm)?triggerConfig.thresholds_cm.map(Number).filter((n:number)=>Number.isFinite(n)&&n>0).sort((a:number,b:number)=>a-b):[];if(!thresholds.length)return reply.code(400).send({error:'Ajoute au moins un seuil de neige'});triggerConfig.thresholds_cm=[...new Set(thresholds)]}if(triggerType==='weekly'){const visits=Math.max(1,Math.min(7,Math.round(Number(triggerConfig.visits_per_week||1))));triggerConfig.visits_per_week=visits}const r=await pool.query(`INSERT INTO recurring_service_plans(category_id,name,description,trigger_type,trigger_config,pricing_type,price_cents,same_team,max_interventions,active,starts_at,ends_at) VALUES($1,$2,$3,$4,$5::jsonb,$6,$7,$8,$9,TRUE,$10,$11) RETURNING *`,[categoryId,name,description,triggerType,JSON.stringify(triggerConfig),pricingType,priceCents,sameTeam,maxInterventions,startsAt,endsAt]);return reply.code(201).send({plan:r.rows[0]})});
app.post('/api/admin/service-plans/:id',async(request,reply)=>{if(!requireAdmin(request,reply))return;const{id}=request.params as any,b=request.body as any,categoryId=String(b?.categoryId||'').trim(),name=String(b?.name||'').trim(),description=String(b?.description||'').trim()||null,triggerType=String(b?.triggerType||'weekly'),triggerConfig=b?.triggerConfig&&typeof b.triggerConfig==='object'?b.triggerConfig:{},pricingType=String(b?.pricingType||'per_minute'),priceCents=Math.max(0,Math.round(Number(b?.priceCents||0))),sameTeam=Boolean(b?.sameTeam),maxInterventions=b?.maxInterventions==null||b.maxInterventions===''?null:Math.max(1,Math.round(Number(b.maxInterventions))),startsAt=b?.startsAt||null,endsAt=b?.endsAt||null;if(!categoryId||!name)return reply.code(400).send({error:'Catégorie et nom requis'});if(!['per_minute','per_visit','monthly','seasonal'].includes(pricingType))return reply.code(400).send({error:'Type de prix invalide'});if(triggerType==='snow_accumulation'){const thresholds=Array.isArray(triggerConfig.thresholds_cm)?triggerConfig.thresholds_cm.map(Number).filter((n:number)=>Number.isFinite(n)&&n>0).sort((a:number,b:number)=>a-b):[];if(!thresholds.length)return reply.code(400).send({error:'Ajoute au moins un seuil de neige'});triggerConfig.thresholds_cm=[...new Set(thresholds)]}if(triggerType==='weekly')triggerConfig.visits_per_week=Math.max(1,Math.min(7,Math.round(Number(triggerConfig.visits_per_week||1))));const r=await pool.query(`UPDATE recurring_service_plans SET category_id=$1,name=$2,description=$3,trigger_type=$4,trigger_config=$5::jsonb,pricing_type=$6,price_cents=$7,same_team=$8,max_interventions=$9,starts_at=$10,ends_at=$11,updated_at=NOW() WHERE id=$12 RETURNING *`,[categoryId,name,description,triggerType,JSON.stringify(triggerConfig),pricingType,priceCents,sameTeam,maxInterventions,startsAt,endsAt,id]);if(!r.rowCount)return reply.code(404).send({error:'Abonnement introuvable'});return{plan:r.rows[0]}});
app.post('/api/admin/service-plans/:id/toggle',async(request,reply)=>{if(!requireAdmin(request,reply))return;const{id}=request.params as any,active=Boolean((request.body as any)?.active);const r=await pool.query('UPDATE recurring_service_plans SET active=$1,updated_at=NOW() WHERE id=$2 RETURNING *',[active,id]);if(!r.rowCount)return reply.code(404).send({error:'Abonnement introuvable'});return{plan:r.rows[0]}});
app.post('/api/admin/service-plans/:id/delete',async(request,reply)=>{if(!requireAdmin(request,reply))return;const{id}=request.params as any,used=await pool.query('SELECT COUNT(*)::int count FROM client_subscriptions WHERE plan_id=$1',[id]);if(Number(used.rows[0]?.count||0)>0)return reply.code(409).send({error:'Ce plan a déjà des abonnements clients. Désactive-le plutôt que de le supprimer.'});const r=await pool.query('DELETE FROM recurring_service_plans WHERE id=$1 RETURNING id',[id]);if(!r.rowCount)return reply.code(404).send({error:'Abonnement introuvable'});return{ok:true}});
app.get('/api/admin/client-subscriptions',async(request,reply)=>{if(!requireAdmin(request,reply))return;const r=await pool.query(`SELECT s.*,c.name client_name,p.name plan_name,cat.name category_name FROM client_subscriptions s JOIN clients c ON c.id=s.client_id JOIN recurring_service_plans p ON p.id=s.plan_id JOIN categories cat ON cat.id=p.category_id ORDER BY s.created_at DESC`);return{subscriptions:r.rows}});

app.get('/api/admin/finance',async(request,reply)=>{if(!requireAdmin(request,reply))return;const payments=await pool.query(`SELECT pay.*,m.client_id,cl.name client_name,c.name category_name FROM payments pay JOIN missions m ON m.id=pay.mission_id LEFT JOIN clients cl ON cl.id=m.client_id LEFT JOIN categories c ON c.id=m.category_id ORDER BY pay.created_at DESC LIMIT 200`);const payouts=await pool.query(`SELECT pp.*,p.name provider_name,c.name category_name FROM provider_payouts pp JOIN providers p ON p.id=pp.provider_id JOIN missions m ON m.id=pp.mission_id LEFT JOIN categories c ON c.id=m.category_id ORDER BY pp.created_at DESC LIMIT 200`);return{payments:payments.rows,payouts:payouts.rows}});
app.post('/api/admin/missions/:id/assign',async(request,reply)=>{if(!requireAdmin(request,reply))return;const{id}=request.params as any,b=request.body as any,providerId=Number(b?.providerId);if(!providerId)return reply.code(400).send({error:'providerId is required'});const p=await pool.query(`SELECT id FROM providers WHERE id=$1 AND status='active'`,[providerId]);if(!p.rowCount)return reply.code(404).send({error:'active provider not found'});const r=await pool.query(`UPDATE missions SET provider_id=$1,status='assigned',updated_at=NOW() WHERE id=$2 AND status NOT IN('completed','cancelled') RETURNING *`,[providerId,id]);if(!r.rowCount)return reply.code(409).send({error:'mission cannot be assigned'});await pool.query(`UPDATE mission_offers SET status=CASE WHEN provider_id=$1 THEN 'accepted' ELSE 'expired' END,responded_at=NOW() WHERE mission_id=$2`,[providerId,id]);return{mission:r.rows[0]}});
app.post('/api/admin/missions/:id/redispatch',async(request,reply)=>{if(!requireAdmin(request,reply))return;const{id}=request.params as any,m=await pool.query(`SELECT category_id FROM missions WHERE id=$1 AND status NOT IN('completed','cancelled')`,[id]);if(!m.rowCount)return reply.code(404).send({error:'mission not found'});await pool.query(`UPDATE missions SET provider_id=NULL,status='requested',updated_at=NOW() WHERE id=$1`,[id]);await pool.query(`UPDATE mission_offers SET status='expired',responded_at=NOW() WHERE mission_id=$1 AND status='pending'`,[id]);const offersCreated=await dispatchMission(Number(id),m.rows[0].category_id);return{ok:true,offersCreated}});
app.post('/api/admin/missions/:id/cancel',async(request,reply)=>{if(!requireAdmin(request,reply))return;const{id}=request.params as any,r=await pool.query(`UPDATE missions SET status='cancelled',updated_at=NOW() WHERE id=$1 AND status NOT IN('completed','cancelled') RETURNING *`,[id]);if(!r.rowCount)return reply.code(409).send({error:'mission cannot be cancelled'});await pool.query(`UPDATE mission_offers SET status='expired',responded_at=NOW() WHERE mission_id=$1 AND status='pending'`,[id]);return{mission:r.rows[0]}});
app.post('/api/admin/providers/:id/status',async(request,reply)=>{if(!requireAdmin(request,reply))return;const{id}=request.params as any,b=request.body as any,status=String(b?.status||'');if(!['active','suspended','inactive'].includes(status))return reply.code(400).send({error:'invalid status'});const r=await pool.query(`UPDATE providers SET status=$1,is_online=CASE WHEN $1='active' THEN is_online ELSE FALSE END,updated_at=NOW() WHERE id=$2 RETURNING *`,[status,id]);if(!r.rowCount)return reply.code(404).send({error:'provider not found'});return{provider:r.rows[0]}});
app.post('/api/admin/providers/:id/online',async(request,reply)=>{if(!requireAdmin(request,reply))return;const{id}=request.params as any,b=request.body as any;if(typeof b?.online!=='boolean')return reply.code(400).send({error:'online boolean is required'});const r=await pool.query(`UPDATE providers SET is_online=$1,last_online_at=CASE WHEN $1 THEN NOW() ELSE last_online_at END,updated_at=NOW() WHERE id=$2 AND status='active' RETURNING *`,[b.online,id]);if(!r.rowCount)return reply.code(409).send({error:'provider must be active'});return{provider:r.rows[0]}});
app.post('/api/admin/payouts/:id/status',async(request,reply)=>{if(!requireAdmin(request,reply))return;const{id}=request.params as any,b=request.body as any,status=String(b?.status||'');if(!['waiting_payment','holding','ready','paid','blocked'].includes(status))return reply.code(400).send({error:'invalid payout status'});const r=await pool.query(`UPDATE provider_payouts SET status=$1,paid_at=CASE WHEN $1='paid' THEN NOW() ELSE paid_at END,updated_at=NOW() WHERE id=$2 RETURNING *`,[status,id]);if(!r.rowCount)return reply.code(404).send({error:'payout not found'});return{payout:r.rows[0]}});

app.addHook('onClose',async()=>{await pool.end()});const port=Number(process.env.PORT??3000),host=process.env.HOST??'0.0.0.0';initializeDatabase().then(async()=>{await registerPushRoutes(app,pool,currentUser);return app.listen({port,host})}).catch(error=>{app.log.error(error);process.exit(1)});
